    "date": "8 Octobre 2026",
    "datePublished": "2026-10-08T22:08:32+00:00",
    "readTime": "5 min de lecture",
    "duration": "PT15M00S",
    "thumbnail": "https://i1.ytimg.com/vi/8JJFZ_rkqRk/hqdefault.jpg",
